select now() as n, curdate() as cd, curtime() as ct, year(at) as y, month(at) as m, date(at) as d, time(at) as t, unix_timestamp(at) as u, date_add(day, interval 1 day) as tomorrow, at + interval 1 hour as later, datediff(day, day) as dd, timediff(t, t) as td, date_format(at, '%Y') as fmt, str_to_date(v, '%Y-%m-%d') as parsed, from_unixtime(whole) as fu, timestampdiff(second, at, at) as tsd, extract(year from at) as ex, last_day(day) as ld, makedate(2026, whole) as md, sec_to_time(whole) as stt, utc_timestamp() as ut from everything
